Implementation details:

Define state enumeration: eState (USINT) with values: IDLE = 0, MOVING = 1, WAITING = 2, FINISHED = 3.

But we can just use USINT constants.

Now code structure:

FUNCTION_BLOCK FB
VAR_INPUT
    processLength: USINT;
    sensor1: BOOL;
    sensor2: BOOL;
    sensor3: BOOL;
    sensor4: BOOL;
    sensor5: BOOL;
    station1Start: BOOL;
    station2Complete: BOOL;
    station3Complete: BOOL;
    station4Complete: BOOL;
    processSequence: ARRAY[1..8] OF USINT;
END_VAR
VAR_OUTPUT
    conveyorLeft: BOOL;
    conveyorRight: BOOL;
END_VAR
VAR
    state: USINT := 0;
    currentStepIndex: USINT := 0;
    currentStation: USINT := 1;
    targetStation: USINT := 0;
    prevStation1Start: BOOL := FALSE;
    prevStation2Complete: BOOL := FALSE;
    prevStation3Complete: BOOL := FALSE;
    prevStation4Complete: BOOL := FALSE;
    firstScan: BOOL := TRUE;
    invalidProcess: BOOL := FALSE;
    movingStarted: BOOL := FALSE;
END_VAR

Now we implement the logic in ST.

We need to use IF statements for state machine. Since we cannot use CASE? We can use CASE state OF ... but we can also use IF-ELSE. Let's use CASE for readability.

We'll write:

// First scan validation
IF firstScan THEN
    firstScan := FALSE;
    IF processLength < 1 OR processLength > 8 THEN
        invalidProcess := TRUE;
        // Ensure conveyors off and idle
        conveyorLeft := FALSE;
        conveyorRight := FALSE;
        state := 0; // IDLE
        // Skip further processing
        // Update prev inputs and exit
        prevStation1Start := station1Start;
        prevStation2Complete := station2Complete;
        prevStation3Complete := station3Complete;
        prevStation4Complete := station4Complete;
        RETURN;
    ELSE
        invalidProcess := FALSE;
    END_IF
END_IF

// Compute rising edges
VAR
    station1StartRising: BOOL;
    station2CompleteRising: BOOL;
    station3CompleteRising: BOOL;
    station4CompleteRising: BOOL;
END_VAR

station1StartRising := station1Start AND NOT prevStation1Start;
station2CompleteRising := station2Complete AND NOT prevStation2Complete;
station3CompleteRising := station3Complete AND NOT prevStation3Complete;
station4CompleteRising := station4Complete AND NOT prevStation4Complete;

// Main state machine
CASE state OF
    0: // IDLE
        // Reset outputs
        conveyorLeft := FALSE;
        conveyorRight := FALSE;
        // Start condition
        IF sensor1 AND station1StartRising THEN
            // Initialize
            currentStepIndex := 1;
            currentStation := 1;
            targetStation := processSequence[1];
            movingStarted := FALSE;
            state := 1; // MOVING
        END_IF

    1: // MOVING
        // If target is same as current, treat as arrived
        IF targetStation = currentStation THEN
            conveyorLeft := FALSE;
            conveyorRight := FALSE;
            IF targetStation = 5 THEN
                state := 3; // FINISHED
            ELSE
                state := 2; // WAITING_FOR_COMPLETION
            END_IF;
            // Reset moving flag
            movingStarted := FALSE;
        ELSE
            // Determine direction
            IF targetStation > currentStation THEN
                conveyorRight := TRUE;
                conveyorLeft := FALSE;
            ELSIF targetStation < currentStation THEN
                conveyorLeft := TRUE;
                conveyorRight := FALSE;
            ELSE
                conveyorRight := FALSE;
                conveyorLeft := FALSE;
            END_IF

            // Check arrival after moving started
            IF NOT movingStarted THEN
                movingStarted := TRUE;
            ELSE
                // Check sensor for target station
                IF (targetStation = 1 AND sensor1) OR
                   (targetStation = 2 AND sensor2) OR
                   (targetStation = 3 AND sensor3) OR
                   (targetStation = 4 AND sensor4) OR
                   (targetStation = 5 AND sensor5) THEN
                    // Arrived
                    conveyorLeft := FALSE;
                    conveyorRight := FALSE;
                    currentStation := targetStation;
                    movingStarted := FALSE;
                    IF targetStation = 5 THEN
                        state := 3; // FINISHED
                    ELSE
                        state := 2; // WAITING_FOR_COMPLETION
                    END_IF;
                END_IF
            END_IF
        END_IF

    2: // WAITING_FOR_COMPLETION
        // Ensure conveyors stopped
        conveyorLeft := FALSE;
        conveyorRight := FALSE;
        // Check for completion signal rising edge
        IF (currentStation = 2 AND station2CompleteRising) OR
           (currentStation = 3 AND station3CompleteRising) OR
           (currentStation = 4 AND station4CompleteRising) THEN
            // Increment step index
            currentStepIndex := currentStepIndex + 1;
            // Set new target
            targetStation := processSequence[currentStepIndex];
            movingStarted := FALSE;
            state := 1; // MOVING
        END_IF

    3: // FINISHED
        conveyorLeft := FALSE;
        conveyorRight := FALSE;
        // If product removed (sensor5 false) then go to IDLE
        IF NOT sensor5 THEN
            state := 0; // IDLE
        END_IF

END_CASE

// Update previous inputs for edge detection
prevStation1Start := station1Start;
prevStation2Complete := station2Complete;
prevStation3Complete := station3Complete;
